import { z } from "zod";
export const layerSchema = z.object({
  id: z.string().min(1).max(100),
  name: z.string().min(1).max(100),
  type: z.enum(["background", "text", "image", "shape"]),
  x: z.number().min(-1920).max(3840),
  y: z.number().min(-1080).max(2160),
  width: z.number().min(1).max(3840),
  height: z.number().min(1).max(2160),
  fill: z.string().max(100),
  text: z.string().max(1000).optional(),
  fontSize: z.number().min(8).max(400).optional(),
  src: z
    .string()
    .max(16000000)
    .regex(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/)
    .optional(),
  opacity: z.number().min(0).max(1),
  shadowEnabled:z.boolean().optional(),
  shadowColor:z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),
  shadowOpacity:z.number().min(0).max(1).optional(),
  shadowBlur:z.number().min(0).max(200).optional(),
  shadowOffsetX:z.number().min(-500).max(500).optional(),
  shadowOffsetY:z.number().min(-500).max(500).optional(),
  visible: z.boolean(),
  locked: z.boolean(),
  aspectLocked: z.boolean().optional(),
  mask:z.enum(['none','rounded','ellipse']).optional(),
  cornerRadius:z.number().min(0).max(1080).optional(),
  imageFit:z.enum(['stretch','cover','contain']).optional(),
  imageCrop:z.object({x:z.number().min(0).max(.99),y:z.number().min(0).max(.99),width:z.number().min(.01).max(1),height:z.number().min(.01).max(1)}).refine(c=>c.x+c.width<=1.000001&&c.y+c.height<=1.000001).optional(),
  flipX:z.boolean().optional(),
  flipY:z.boolean().optional(),
  groupId: z.string().max(100).optional(),
  groupName: z.string().max(100).optional(),
  rotation: z.number().min(-360).max(360).default(0),
});
export type Layer = z.infer<typeof layerSchema>;
export const projectSchema = z
  .object({
    version: z.literal(1),
    packagingVersion: z.literal(2).optional(),
    channelContext:z.object({channelId:z.string().regex(/^\d{1,20}$/),template:z.string().max(100),liveType:z.string().max(100),scene:z.string().max(100)}).optional(),
    protectedAreaEnabled:z.boolean().optional(),
    footageLocked:z.boolean().optional(),
    footageIndex:z.number().int().min(0).max(100).optional(),
    footageTransform:z.object({x:z.number().min(-2).max(2),y:z.number().min(-2).max(2),scale:z.number().min(.1).max(4)}).optional(),
    footageViewport:z.object({x:z.number().min(0).max(1),y:z.number().min(0).max(1),width:z.number().positive().max(1),height:z.number().positive().max(1)}).refine(v=>v.x+v.width<=1&&v.y+v.height<=1).optional(),
    warmupReference:z.string().max(8000000).regex(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/).optional(),
    warmupContext:z.string().max(12000).optional(),
    previewImage:z.string().max(8000000).regex(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/).optional(),
    protectedArea: z.object({x:z.number().min(0),y:z.number().min(0),width:z.number().min(24),height:z.number().min(24)}).optional(),
    name: z.string().min(1).max(100),
    width: z.union([z.literal(1920), z.literal(1080)]),
    height: z.union([z.literal(1080), z.literal(1920)]),
    mode: z.enum(["overlay", "warmup"]).default("warmup"),
    scene: z.number().int().min(0).max(3).default(0),
    reservePpt:z.boolean().optional(),
    templateStyle:z.enum(['studio-v3','ai-v1']).optional(),
    layers: z.array(layerSchema).max(100),
  })
  .refine(
    (p) =>
      (p.width === 1920 && p.height === 1080) ||
      (p.width === 1080 && p.height === 1920),
    "仅支持16:9或9:16",
  )
  .refine(p => !p.protectedArea || (p.protectedArea.x + p.protectedArea.width <= p.width + 1 && p.protectedArea.y + p.protectedArea.height <= p.height + 1), "内容保留区必须在画布内")
  .refine(
    (p) => new Set(p.layers.map((l) => l.id)).size === p.layers.length,
    "图层ID不能重复",
  );
