export const patchSchema = z.object({
  id: z.string(),
  changes: z
    .object({
      text: z.string().max(1000).optional(),
      fill: z
        .string()
        .regex(/^#[0-9a-fA-F]{6}$/)
        .optional(),
      x: z.number().min(0).max(1920).optional(),
      y: z.number().min(0).max(1920).optional(),
      fontSize: z.number().min(8).max(400).optional(),
      opacity: z.number().min(0).max(1).optional(),
      visible: z.boolean().optional(),
      width: z.number().min(1).max(1920).optional(),
      height: z.number().min(1).max(1920).optional(),
    })
    .strict(),
});
export const operationsSchema = z.array(patchSchema).min(1).max(30);
export function applyOps(p: Project, raw: unknown): Project {
  const ops = operationsSchema.parse(raw);
  for (const op of ops)
    if (!p.layers.some((l) => l.id === op.id)) throw Error("找不到目标图层");
  return projectSchema.parse({
    ...p,
    layers: p.layers.map((l) => ({
      ...l,
      ...ops
        .filter((o) => o.id === l.id)
        .reduce((a, o) => ({ ...a, ...o.changes }), {}),
    })),
  });
}
export function demoCommand(p: Project, q: string): Project {
  let l = p.layers.find((l) =>
    q.toLowerCase().includes("logo")
      ? l.name.toLowerCase().includes("logo")
      : q.includes("姓名条")
        ? l.id === "姓名条"
        : q.includes("底部信息")
          ? l.id === "底部信息"
          : q.includes("副标题")
            ? l.id === "副标题"
            : q.includes("背景")
              ? l.type === "background"
              : l.id === "活动标题",
  );
  if (!l) throw Error("请先上传 Logo，再调整它的位置");
  const c: Record<string, unknown> = {};
  const title = q.match(
    /(?:标题改成|标题改为|标题设为|姓名条改成|底部信息改成)[“「"']?(.+?)[”」"']?$/,
  );
  if (title) c.text = title[1].replace(/[。]$/, "");
  const size = q.match(/(放大|缩小)\s*(\d+)\s*%/);
  if (size && l.fontSize)
    c.fontSize = Math.min(
      400,
      Math.max(
        8,
        l.fontSize *
          (1 + ((size[1] === "放大" ? 1 : -1) * Number(size[2])) / 100),
      ),
    );
  const colors: Record<string, string> = {
    金色: "#dfb778",
    蓝色: "#235ff5",
    白色: "#ffffff",
    黑色: "#111827",
    紫色: "#7c58bb",
    红色: "#d94b4b",
    绿色: "#498c73",
  };
  for (const [word, color] of Object.entries(colors))
    if (q.includes(word)) c.fill = color;
  const hex = q.match(/#[0-9a-fA-F]{6}/);
  if (hex) c.fill = hex[0];
  if (q.includes("右上")) {
    c.x = p.width - l.width - 60;
    c.y = 80;
  }
  if (q.includes("左上")) {
    c.x = 100;
    c.y = 80;
  }
  if (q.includes("居中")) {
    c.x = (p.width - l.width) / 2;
    c.y = (p.height - l.height) / 2;
  }
  if (!Object.keys(c).length)
    throw Error(
      "演示模式支持：标题改成…、标题放大20%、标题颜色改成金色、Logo移动到右上角。自由指令需配置文字 AI。",
    );
  return applyOps(p, [{ id: l.id, changes: c }]);
}

export type Ratio = "landscape" | "portrait";
export function safeArea(p: Pick<Project, "width" | "height"> & Partial<Pick<Project,"protectedArea">>) {
  if (p.protectedArea) return p.protectedArea;
  const portrait = p.height > p.width;
  return portrait
    ? { x: 50, y: 230, width: 980, height: 1210 }
    : { x: 64, y: 160, width: 1792, height: 660 };
}
