export function resizeProject(p: Project, ratio: Ratio): Project {
  const width = ratio === "portrait" ? 1080 : 1920,
    height = ratio === "portrait" ? 1920 : 1080;
  if (p.width === width && p.height === height) return p;
  const sx = width / p.width,
    sy = height / p.height,
    scale = Math.min(sx, sy);
  return {
    ...p,
    width,
    height,
    ...(p.protectedArea ? {protectedArea:{x:p.protectedArea.x*sx,y:p.protectedArea.y*sy,width:p.protectedArea.width*sx,height:p.protectedArea.height*sy}} : {}),
    layers: p.layers.map((l) =>
      l.type === "background"
        ? { ...l, width, height }
        : {
            ...l,
            x: l.x * sx,
            y: l.y * sy,
            width: l.width * (l.type === "image" || l.src ? scale : sx),
            height: l.height * (l.type === "image" || l.src ? scale : sy),
            ...(l.fontSize
              ? { fontSize: Math.max(8, l.fontSize * scale) }
              : {}),
          },
    ),
  };
}

