/** Upgrade former repeated backplates once; keep user wording and custom layers. */
export function applyBroadcastMaterials(p: Project): Project {
  if(p.mode==="overlay") p={...p,layers:p.layers.filter(l=>!(l.id==="background"&&l.type==="background"&&!l.src&&(l.opacity===0||l.fill==="transparent")))};
  if (p.mode !== "overlay" || p.packagingVersion === 2) return p;
  const next = template(p.scene, p.height > p.width ? "portrait" : "landscape");
  const old = new Map(p.layers.map((l) => [l.id, l]));
  const defaultColors = new Set(
    styles
      .flatMap((s) => [s.fg, s.bg, s.accent])
      .concat(["#fff7ec", "#ffffff"]),
  );
  next.layers = next.layers.map((l) => {
    const prior = old.get(l.id);
    if (!prior) return l;
    const customSource = prior.src && !prior.name.includes("AI贴片");
    return {
      ...l,
      visible: prior.visible,
      locked: prior.locked,
      ...(prior.type === "text"
        ? {
            text: prior.text,
            ...(!defaultColors.has(prior.fill) ? { fill: prior.fill } : {}),
          }
        : {}),
      ...(customSource
        ? {
            src: prior.src,
            x: prior.x,
            y: prior.y,
            width: prior.width,
            height: prior.height,
          }
        : {}),
    };
  });
  const builtin = new Set(next.layers.map((l) => l.id));
  next.layers.push(...p.layers.filter((l) => !builtin.has(l.id)));
  return { ...next, name: p.name, ...(p.protectedArea ? {protectedArea:p.protectedArea} : {}) };
}

/** New work starts without template decoration; templates remain opt-in. */
export function blankProject(scene=0,ratio:Ratio="landscape",mode:Project["mode"]="overlay"):Project{
 const p=template(scene,ratio,mode);
 return projectSchema.parse({...p,packagingVersion:2,name:"未命名作品",layers:mode==="overlay"?[]:[{id:"background",name:"背景",type:"background",x:0,y:0,width:p.width,height:p.height,rotation:0,opacity:1,visible:true,locked:true,fill:"#ffffff"}]});
}

export function newLocalId(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = (bytes[6] & 15) | 64;
  bytes[8] = (bytes[8] & 63) | 128;
  const hex = Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;
}
